const closures=[];for(var i=0;i<3;i++)closures.push(function(){return i});print("var closures all see final i:",closures.map(function(r){return r()}).join(","));const closures2=[];for(var j=0;j<3;j++)(function(r){closures2.push(function(){return r})})(j);print("IIFE-captured var closures:",closures2.map(function(r){return r()}).join(","));